create table if not exists public.website_join_leads(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),reference text unique not null,source text not null default 'website_join',lead_type text not null check(lead_type in('career_candidate','internship_candidate','seller_referral')),first_name text,last_name text,phone text,email text,location text,current_professional_status text,sales_experience text,motivation text,availability text,school text,education text,start_date date,end_date date,duration_weeks integer,preferred_missions text[] not null default '{}',property_type text,island text,city text,area text,owner_first_name text,owner_last_name text,owner_phone text,owner_phone_normalized text,owner_email text,owner_email_normalized text,seller_project_stage text,referrer_first_name text,referrer_last_name text,referrer_phone text,referrer_email text,notes text,third_party_consent_at timestamptz,privacy_consent_at timestamptz not null,possible_duplicate boolean not null default false,duplicate_lead_id uuid references public.website_join_leads(id),pipeline text not null default 'new' check(pipeline in('new','reviewing','contacted','accepted','declined','converted')),next_action text,next_follow_up timestamptz,sheet_sync_status text not null default 'pending',metadata jsonb not null default '{}');
create index if not exists website_join_type_idx on public.website_join_leads(lead_type,created_at desc);create index if not exists website_join_owner_phone_idx on public.website_join_leads(owner_phone_normalized) where owner_phone_normalized is not null;create index if not exists website_join_pipeline_idx on public.website_join_leads(pipeline,created_at desc);
alter table public.website_join_leads enable row level security;
create policy "foncier admins website join leads" on public.website_join_leads for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());
